<?php sr_hero('Raw data library', 'JSON Library', 'Every loaded JSON file gets a source page with human summary, normalized records, and raw JSON one click away.'); $dataStatus = sr_data_status(); ?><section class="panel"><h2>Active data folder</h2><p><code><?= sr_e($dataStatus['active_root']); ?></code></p><p><b><?= sr_e((string)$dataStatus['json_count']); ?></b> JSON files found.</p></section>
